<?php require_student();$id=(int)($_GET['id']??0);$row=db_one('SELECT c.*,ca.category_name,s.name,s.email FROM complaints c JOIN categories ca ON ca.id=c.category_id JOIN students s ON s.id=c.student_id WHERE c.id=? AND c.student_id=?','ii',[$id,student()['id']]);if(!$row){flash('danger','Complaint not found.');redirect('student/my-complaints.php');}$remarks=db_all('SELECT r.*,a.name admin_name FROM remarks r JOIN admins a ON a.id=r.admin_id WHERE r.complaint_id=? ORDER BY r.created_at DESC','i',[$id]);$pageTitle='Complaint Details';require_once __DIR__.'/../includes/header.php'; ?>
<div class="row g-4"><div class="col-lg-3"><?php require __DIR__.'/_sidebar.php'; ?></div><div class="col-lg-9"><div class="dashboard-header mb-4 d-flex justify-content-between align-items-start flex-wrap gap-3"><div><div class="complaint-id mb-2"><?=e($row['complaint_id'])?></div><h1 class="section-title mb-1"><?=e($row['title'])?></h1><div class="small-muted">Submitted <?=e(date('d M Y, h:i A',strtotime($row['created_at'])))?></div></div><span class="badge-soft <?=e(status_class($row['status']))?>"><?=e($row['status'])?></span></div><div class="card mb-4"><div class="card-body"><div class="row g-4 mb-4"><div class="col-sm-4"><div class="detail-label">Category</div><div class="detail-value"><?=e($row['category_name'])?></div></div><div class="col-sm-4"><div class="detail-label">Priority</div><div class="detail-value <?=e(priority_class($row['priority']))?>"><?=e($row['priority'])?></div></div><div class="col-sm-4"><div class="detail-label">Last updated</div><div class="detail-value"><?=e(date('d M Y',strtotime($row['updated_at'])))?></div></div></div><div class="detail-label mb-2">Description</div><p class="mb-0" style="white-space:pre-line"><?=e($row['description'])?></p><?php if($row['attachment']): ?><a class="btn btn-sm btn-outline-primary mt-4" href="<?=e(url('uploads/'.$row['attachment']))?>" target="_blank">View attachment</a><?php endif;?></div></div><div class="card"><div class="card-header"><strong>Administrator remarks</strong></div><div class="card-body"><?php if(!$remarks): ?><div class="empty-state py-4">No remarks have been added yet.</div><?php else: ?><div class="timeline"><?php foreach($remarks as $remark): ?><div class="timeline-item"><div class="fw-semibold"><?=e($remark['admin_name'])?></div><div class="small-muted mb-2"><?=e(date('d M Y, h:i A',strtotime($remark['created_at'])))?></div><div style="white-space:pre-line"><?=e($remark['remark'])?></div></div><?php endforeach;?></div><?php endif;?></div></div></div></div>
